:root {
	/* =========================================
	   AI CUSTOMER SUPPORT TICKET
	   JZ PVT LTD
	   Modern Blue + Cyan Theme
	========================================= */

	/* Typography */
	--font-family: 'Open Sans', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;

	--font-size-body: 13px;
	--font-size-label: 13px;
	--font-size-test-notice: 12px;
	--font-size-input: 14px;
	--font-size-header: 26px;
	--font-size-paragraph: 14px;
	--font-size-link: 13px;
	--font-size-error: 12px;

	--font-size-html-h1: 30px;
	--font-size-html-h2: 22px;
	--font-size-html-h3: 18px;
	--font-size-html-h4: 15px;
	--font-size-html-h5: 13px;
	--font-size-html-h6: 11px;
	--font-size-subheader: 14px;


	/* =========================================
	   COLORS
	========================================= */

	--color-background: #f4f8ff;

	/* AI Brand Colors */
	--color-primary: #2563eb;
	--color-primary-dark: #1d4ed8;
	--color-secondary: #06b6d4;
	--color-accent: #38bdf8;

	/* Header */
	--color-header: #0f172a;
	--color-header-subtext: #64748b;

	/* Card */
	--color-card-bg: rgba(255, 255, 255, 0.97);
	--color-card-border: #dbe5f1;
	--color-card-shadow: rgba(37, 99, 235, 0.10);

	/* Labels */
	--color-label: #334155;

	/* Inputs */
	--color-input-bg: #f8fafc;
	--color-input-border: #d7e1ee;
	--color-input-text: #1e293b;
	--color-placeholder: #94a3b8;

	/* Focus */
	--color-focus-border: #2563eb;
	--color-focus-shadow: rgba(37, 99, 235, 0.16);

	/* Submit */
	--color-submit-btn-bg: #2563eb;
	--color-submit-btn-hover: #1d4ed8;
	--color-submit-btn-text: #ffffff;

	/* Error */
	--color-error: #dc2626;
	--color-required: #ef4444;

	/* Links */
	--color-link: #2563eb;
	--color-html-link: #2563eb;

	/* Clear */
	--color-clear-button-bg: #64748b;

	/* HTML */
	--color-html-text: #334155;


	/* =========================================
	   GRADIENTS
	========================================= */

	--gradient-primary:
		linear-gradient(
			135deg,
			#2563eb 0%,
			#06b6d4 100%
		);

	--gradient-header:
		linear-gradient(
			135deg,
			#0f172a 0%,
			#1e3a8a 55%,
			#0369a1 100%
		);

	--gradient-button:
		linear-gradient(
			135deg,
			#2563eb,
			#06b6d4
		);


	/* =========================================
	   BORDER RADII
	========================================= */

	--border-radius-card: 18px;
	--border-radius-input: 10px;
	--border-radius-button: 10px;
	--border-radius-clear-btn: 50%;
	--card-border-radius: 18px;


	/* =========================================
	   SPACING
	========================================= */

	--padding-container-top: 32px;
	--padding-card: 30px;

	--padding-test-notice-vertical: 12px;
	--padding-test-notice-horizontal: 18px;

	--margin-bottom-card: 20px;

	--padding-form-input: 13px;

	--card-padding: 30px;
	--card-margin-bottom: 20px;


	/* =========================================
	   DIMENSIONS
	========================================= */

	--container-width: 520px;
	--submit-btn-height: 50px;
	--checkbox-size: 18px;


	/* =========================================
	   SHADOWS
	========================================= */

	--box-shadow-card:
		0px 12px 35px rgba(15, 23, 42, 0.08);

	--box-shadow-input:
		0px 4px 14px rgba(37, 99, 235, 0.05);

	--box-shadow-button:
		0px 8px 20px rgba(37, 99, 235, 0.25);


	/* =========================================
	   OTHER
	========================================= */

	--opacity-placeholder: 0.6;

	--transition-fast: 0.2s ease;
	--transition-normal: 0.3s ease;
}


/* =========================================
   BODY
========================================= */

body {
	background:
		radial-gradient(
			circle at top left,
			rgba(37, 99, 235, 0.08),
			transparent 35%
		),
		radial-gradient(
			circle at bottom right,
			rgba(6, 182, 212, 0.08),
			transparent 35%
		),
		var(--color-background);

	font-family: var(--font-family);

	color: var(--color-html-text);
}


/* =========================================
   FORM CARD
========================================= */

.card {
	background: var(--color-card-bg);

	border: 1px solid var(--color-card-border);

	border-radius: var(--border-radius-card);

	box-shadow: var(--box-shadow-card);

	backdrop-filter: blur(12px);

	transition: var(--transition-normal);
}

.card:hover {
	transform: translateY(-2px);

	box-shadow:
		0px 18px 45px rgba(37, 99, 235, 0.12);
}


/* =========================================
   HEADER
========================================= */

h1,
.form-header {
	color: var(--color-header);

	font-weight: var(--font-weight-bold);

	letter-spacing: -0.5px;
}


/* =========================================
   SUBHEADER
========================================= */

.form-subheader {
	color: var(--color-header-subtext);

	line-height: 1.6;
}


/* =========================================
   LABELS
========================================= */

label {
	color: var(--color-label);

	font-weight: 600;

	margin-bottom: 7px;
}


/* =========================================
   INPUTS
========================================= */

input,
textarea,
select {
	width: 100%;

	box-sizing: border-box;

	background: var(--color-input-bg);

	border: 1px solid var(--color-input-border);

	border-radius: var(--border-radius-input);

	color: var(--color-input-text);

	font-size: var(--font-size-input);

	padding: var(--padding-form-input);

	transition: var(--transition-fast);

	box-shadow: var(--box-shadow-input);
}


/* =========================================
   INPUT FOCUS
========================================= */

input:focus,
textarea:focus,
select:focus {
	outline: none;

	border-color: var(--color-focus-border);

	background: #ffffff;

	box-shadow:
		0 0 0 3px var(--color-focus-shadow);
}


/* =========================================
   PLACEHOLDER
========================================= */

input::placeholder,
textarea::placeholder {
	color: var(--color-placeholder);

	opacity: var(--opacity-placeholder);
}


/* =========================================
   TEXTAREA
========================================= */

textarea {
	min-height: 130px;

	resize: vertical;

	line-height: 1.6;
}


/* =========================================
   SUBMIT BUTTON
========================================= */

button[type="submit"] {
	width: 100%;

	height: var(--submit-btn-height);

	border: none;

	border-radius: var(--border-radius-button);

	background: var(--gradient-button);

	color: var(--color-submit-btn-text);

	font-size: 14px;

	font-weight: 600;

	cursor: pointer;

	box-shadow: var(--box-shadow-button);

	transition: var(--transition-normal);
}

button[type="submit"]:hover {
	transform: translateY(-2px);

	background: var(--gradient-primary);

	box-shadow:
		0px 12px 25px rgba(37, 99, 235, 0.30);
}

button[type="submit"]:active {
	transform: translateY(0);
}


/* =========================================
   REQUIRED FIELD
========================================= */

.required {
	color: var(--color-required);
}


/* =========================================
   ERROR
========================================= */

.error {
	color: var(--color-error);

	font-size: var(--font-size-error);

	margin-top: 5px;
}


/* =========================================
   AI BADGE
========================================= */

.ai-badge {
	display: inline-flex;

	align-items: center;

	gap: 6px;

	padding: 6px 12px;

	border-radius: 999px;

	background: rgba(37, 99, 235, 0.08);

	color: var(--color-primary);

	font-size: 12px;

	font-weight: 600;

	border: 1px solid rgba(37, 99, 235, 0.15);
}


/* =========================================
   LINKS
========================================= */

a {
	color: var(--color-link);

	font-weight: 600;

	text-decoration: none;

	transition: var(--transition-fast);
}

a:hover {
	color: var(--color-primary-dark);
}


/* =========================================
   CLEAR BUTTON
========================================= */

button.clear {
	background: var(--color-clear-button-bg);

	color: #ffffff;

	border: none;

	transition: var(--transition-fast);
}

button.clear:hover {
	transform: scale(1.05);
}


/* =========================================
   JZ PVT LTD FOOTER
========================================= */

.form-footer {
	width: 100%;

	text-align: center;

	margin-top: 22px;

	padding-top: 16px;

	border-top: 1px solid #dbe5f1;

	color: #64748b;

	font-size: 12px;

	line-height: 1.5;
}

.form-footer strong {
	color: #2563eb;

	font-weight: 600;
}

.form-footer span {
	opacity: 0.9;
}


/* =========================================
   AI STATUS / PROCESSING
========================================= */

.ai-status {
	display: flex;

	align-items: center;

	justify-content: center;

	gap: 8px;

	margin-top: 12px;

	font-size: 12px;

	color: #64748b;
}


/* =========================================
   RESPONSIVE
========================================= */

@media (max-width: 600px) {

	:root {
		--container-width: 94%;
		--padding-card: 22px;
	}

	.card {
		border-radius: 14px;
	}

	h1,
	.form-header {
		font-size: 22px;
	}

	input,
	textarea,
	select {
		font-size: 14px;
	}

	.form-footer {
		margin-top: 18px;
	}
}

